// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-05-explanation-and-source-berachot.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-05-section-info-every-fragment.md
// Тикеты #6a86f7df · 6a86f7df6f29cb4c367083d2 (мокап S-17); #a5decf4a (строка источника после утверждения).
// Опора: мокап S-17 — у каждого фрагмента каждой ברכה пояснение и ровно одна строка источника; кнопки «שיתוף התפילה» нет.
// ברכות открываются по ключу (как web /prayer/beracha_<base>_<נוסח>) — нужен APP_SCHEME (deep link); без него тест пропускается.
// Несуществующий вариант נוסח (web: HTTP 404) — экран молитвы не появляется за 10 с → вариант пропускается.
import { expect, $$, driver } from '@wdio/globals';
import { qRe, byText, byTextMatches, byLabel, tapText, scrollToText, swipeUp } from '../../helpers/ui.ts';
import { openRoute, hasDeepLinks } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const BASES = [
  'hamotzi', 'mezonot', 'hagefen', 'haetz', 'haadamah', 'shehakol', 'birkat_hamazon', 'meein_shalosh', 'borei_nefashot',
  'shehecheyanu', 'asher_yatzar', 'tefilat_haderech',
];
const SFARAD_ONLY = new Set(['shehecheyanu']);
const SOURCE_LINE = '(הטקסט עדיין לא אושר|מקור: .+אושר על ידי ).*';
const COUNTER = '\\d+ מתוך \\d+';

const q = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
function allByTextMatches(re: string) {
  return driver.isAndroid
    ? $$(`android=new UiSelector().textMatches("${qRe(re)}")`)
    : $$(`-ios predicate string:label MATCHES "${q(re)}" OR value MATCHES "${q(re)}"`);
}
async function sourceLines(maxSwipes = 10) {
  for (let i = 0; i <= maxSwipes; i++) {
    const shown: WebdriverIO.Element[] = [];
    for (const el of await allByTextMatches(SOURCE_LINE)) if (await el.isDisplayed().catch(() => false)) shown.push(el);
    if (shown.length) return shown;
    await swipeUp();
  }
  return [];
}
/** «N מתוך M» или null, если счётчика нет (фрагмент один). */
async function readCounter(): Promise<[number, number] | null> {
  const el = await byTextMatches(COUNTER);
  if (!(await el.isDisplayed().catch(() => false))) return null;
  const m = ((await el.getText()) || '').match(/(\d+) מתוך (\d+)/);
  return m ? [Number(m[1]), Number(m[2])] : null;
}
async function tapNav(label: string) {
  const el = await byText(label);
  if (!(await el.isDisplayed().catch(() => false))) await scrollToText(label);
  await tapText(label);
}
async function waitCounter(expected: string) {
  await driver.waitUntil(async () => { const c = await readCounter(); return !!c && `${c[0]} מתוך ${c[1]}` === expected; },
    { timeoutMsg: `Счётчик не стал «${expected}»` });
}
/** Открыть ключ; true — экран молитвы появился (счётчик или строка источника), false — варианта нет. */
async function openKey(key: string) {
  await toHome();                                    // чтобы не принять счётчик предыдущей молитвы за новый экран
  await openRoute(`/prayer/${key}`);
  return driver.waitUntil(async () =>
    (await (await byTextMatches(COUNTER)).isDisplayed().catch(() => false)) ||
    (await (await byTextMatches(SOURCE_LINE)).isDisplayed().catch(() => false)),
  { timeout: 10000 }).then(() => true, () => false);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-05 Строка источника во всех ברכות (beracha_*), без «שיתוף התפילה» #6a86f7df #a5decf4a @prod-safe', async function () {
    if (!hasDeepLinks()) this.skip();   // ברכות по ключу — только через deep link (APP_SCHEME)
    this.timeout(900000);
    let totalKeys = 0;
    for (const base of BASES) {
      const keys = SFARAD_ONLY.has(base) ? [`beracha_${base}_sfarad`] : [`beracha_${base}_ashkenaz`, `beracha_${base}_sfarad`];
      for (const key of keys) {
        // 1. Открыть ключ; «קודם» до «1 מתוך N» (нет счётчика — фрагмент один).
        if (!(await openKey(key))) continue;
        totalKeys++;
        let c = await readCounter();
        while (c && c[0] > 1) { await tapNav('קודם'); await waitCounter(`${c[0] - 1} מתוך ${c[1]}`); c = [c[0] - 1, c[1]]; }
        const total = c ? c[1] : 1;

        // 2. На каждом фрагменте — ровно одна строка источника, нет «שיתוף התפילה»; «המשך» до последнего.
        for (let i = 1; i <= total; i++) {
          if (total > 1) await waitCounter(`${i} מתוך ${total}`);
          expect((await sourceLines()).length).toBe(1);
          await expect(byLabel('שיתוף התפילה')).not.toBeDisplayed();
          if (i < total) await tapNav('המשך');   // у ברכות нет «סיים תפילה»: на последнем фрагменте «המשך» нет
        }
      }
    }
    expect(totalKeys).toBeGreaterThanOrEqual(1);
  });
});
